window.__votdWeek && window.__votdWeek({"week":"2028-09-04","reading":"Helaman 13–16","days":[{"d":"2028-09-04","ref":"Helaman 13:13","b":"Helaman","c":13,"v":13,"he":"אַךְ אַשְׁרֵי הַשָּׁבִים כִּי אֶחְמֹל עֲלֵיהֶם אַךְ הִנֵּה לוּלֵי הַצַּדִּיקִים אֲשֶׁר בָּעִיר הַגְּדוֹלָה הַזֹּאת הִנֵּה הָיִיתִי מוֹרִיד אֵשׁ מִן־הַשָּׁמַיִם לְהַשְׁמִידָהּ׃","en":"But blessed are they who will repent, for them will I spare. But behold, if it were not for the righteous who are in this great city, behold, I would cause that fire should come down out of heaven and destroy it."},{"d":"2028-09-05","ref":"Helaman 13:24","b":"Helaman","c":13,"v":24,"he":"הֵן אוֹי לָעָם הַזֶּה בַּעֲבוּר הָעֵת הַזֹּאת אֲשֶׁר בָּאָה כִּי תְגָרְשׁוּ אֶת־הַנְּבִיאִים וְתִלְעֲגוּ לָהֶם וְתִרְגְּמוּ אוֹתָם בָּאֲבָנִים וְתַהַרְגוּם וְתַעֲשׂוּ לָהֶם כׇּל־עָוֹן כַּאֲשֶׁר עָשׂוּ בִּימֵי קֶדֶם׃","en":"Yea, wo unto this people, because of this time which has arrived, that ye do cast out the prophets, and do mock them, and cast stones at them, and do slay them, and do all manner of iniquity unto them, even as they did of old time."},{"d":"2028-09-06","ref":"Helaman 14:15","b":"Helaman","c":14,"v":15,"he":"כִּי הִנֵּה מוֹת יָמוּת לְמַעַן תָּבֹא הַיְשׁוּעָה אַף עָלָיו וְנָכוֹן כִּי יָמוּת לְהָבִיא תְּקוּמַת הַמֵּתִים לְמַעַן יוּבְאוּ בְּנֵי־הָאָדָם לִפְנֵי יְהוָה׃","en":"For behold, he surely must die that salvation may come; yea, it behooveth him and becometh expedient that he dieth, to bring to pass the resurrection of the dead, that thereby men may be brought into the presence of the Lord."},{"d":"2028-09-07","ref":"Helaman 14:23","b":"Helaman","c":14,"v":23,"he":"וְהִנֵּה יִהְיוּ סְעָרוֹת גְּדוֹלוֹת וְהָרִים רַבִּים יֻשְׁפְּלוּ כַּבִּקְעָה וּמְקוֹמוֹת רַבִּים הַנִּקְרָאִים כַּיּוֹם בְּקָעוֹת יִהְיוּ לְהָרִים גְּבֹהִים מְאֹד׃","en":"And behold, there shall be great tempests, and there shall be many mountains laid low, like unto a valley, and there shall be many places which are now called valleys which shall become mountains, whose height is great."},{"d":"2028-09-08","ref":"Helaman 15:8","b":"Helaman","c":15,"v":8,"he":"לָכֵן כׇּל־הַבָּאִים לָזֶה יְדַעְתֶּם מִנַּפְשְׁכֶם כִּי אֵיתָנִים וַחֲזָקִים הֵם בָּאֱמוּנָה וּבַדָּבָר אֲשֶׁר־בּוֹ נַעֲשׂוּ חׇפְשִׁים׃","en":"Therefore, as many as have come to this, ye know of yourselves are firm and steadfast in the faith, and in the thing wherewith they have been made free."},{"d":"2028-09-09","ref":"Helaman 16:13","b":"Helaman","c":16,"v":13,"he":"וַיְהִי בִּשְׁנַת תִּשְׁעִים לִמְשֹׁל הַשֹּׁפְטִים נִתְּנוּ אֹתוֹת גְּדוֹלִים לָעָם וּמוֹפְתִים וַיָּחֵלּוּ דִּבְרֵי הַנְּבִיאִים לְהִמָּלֵא׃","en":"But it came to pass in the ninetieth year of the reign of the judges, there were great signs given unto the people, and wonders; and the words of the prophets began to be fulfilled."},{"d":"2028-09-10","ref":"Helaman 16:14","b":"Helaman","c":16,"v":14,"he":"וּמַלְאָכִים נִרְאוּ אֶל־אֲנָשִׁים חֲכָמִים וַיַּגִּידוּ לָהֶם בְּשׂוֹרַת שִׂמְחָה גְדוֹלָה וּבַשָּׁנָה הַזֹּאת הֵחֵלּוּ הַכְּתוּבִים לְהִמָּלֵא׃","en":"And angels did appear unto men, wise men, and did declare unto them glad tidings of great joy; thus in this year the scriptures began to be fulfilled."}]});
